// 순서: 시험 방송·기록 → 재생·정지 → 차량 명령 연결 → 실제 재생 상태.
const stations=[{title:'Radio Paradise · Main',url:'https://stream.radioparadise.com/aac-128'},{title:'Radio Paradise · Mellow',url:'https://stream.radioparadise.com/mellow-128'}];
const by=id=>document.getElementById(id),audio=by('radio'),session=navigator.mediaSession,key='jadu:tesla:media-test:1116vc1',labels={play:'재생',pause:'일시정지',stop:'정지',previoustrack:'이전',nexttrack:'다음'},countIds={play:'play',pause:'pause',previoustrack:'previous',nexttrack:'next'};
let index=0,wanted=false,loading=false,failed=false,request=0,rows=[],supported=[];
const counts={play:0,pause:0,previoustrack:0,nexttrack:0};
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(Array.isArray(saved?.rows)){rows=saved.rows.slice(-40);for(const action in counts)counts[action]=Math.max(0,Number(saved.counts?.[action])||0);}}catch{}
function drawLog(){for(const[action,id]of Object.entries(countIds))by('count-'+id).textContent=counts[action];const latest=rows.filter(row=>row.source==='external').at(-1);by('last-command').textContent=latest?(labels[latest.action]||latest.action)+' 명령 수신 · '+new Date(latest.time).toLocaleTimeString('ko-KR'):'아직 외부 명령을 받지 않았어요.';by('log').replaceChildren();for(const row of rows.slice().reverse()){const li=document.createElement('li');li.textContent=new Date(row.time).toLocaleTimeString('ko-KR')+' · '+(row.source==='external'?'차량·브라우저':'화면')+' · '+(labels[row.action]||row.action)+' · '+row.station;by('log').append(li);}}
function record(action,source){if(source==='external'&&action in counts)counts[action]++;rows.push({time:new Date().toISOString(),action,source,station:stations[index].title});rows=rows.slice(-40);try{localStorage.setItem(key,JSON.stringify({rows,counts}));}catch{}drawLog();}
function state(value){if(session)try{session.playbackState=value;}catch{}}
function paint(){const busy=wanted&&(loading||!audio.paused);by('play').setAttribute('aria-label',busy?'일시정지':'재생');by('play-label').textContent=busy?'일시정지':'재생';by('play').querySelector('path').setAttribute('d',busy?'M7 5h4v14H7zM14 5h4v14h-4z':'M8 5v14l12-7z');by('station-title').textContent=stations[index].title;}
function metadata(){if(!session)return;try{session.metadata=new MediaMetadata({title:stations[index].title,artist:'자두 차량 버튼 테스트',album:'인터넷 라디오',artwork:[{src:'https://kt-soft.github.io/Jadu-Web/Tesla/assets/jadu-paw-media-1112.png',sizes:'512x512',type:'image/png'}]});session.setPositionState?.();}catch{}}
async function start(change=false){const generation=++request;wanted=true;loading=true;by('play-status').textContent='방송에 연결하고 있어요…';if(change||failed||!audio.getAttribute('src')){failed=false;audio.src=stations[index].url;}paint();try{await audio.play();if(generation!==request||!wanted)return;}catch(error){if(generation!==request||!wanted)return;wanted=false;loading=false;failed=error.name!=='NotAllowedError';state('paused');by('play-status').textContent=error.name==='NotAllowedError'?'화면의 재생 버튼을 한 번 눌러 주세요.':'방송을 연결하지 못했어요. 다시 재생하거나 다음 채널을 눌러 주세요.';paint();}}
function pause(clear=false){request++;wanted=false;loading=false;audio.pause();if(clear){audio.removeAttribute('src');audio.load();state('none');}else state('paused');by('play-status').textContent=clear?'정지했어요.':'일시정지';paint();}
function command(action,source){record(action,source);if(action==='play')start();else if(action==='pause'||action==='stop')pause(action==='stop');else{index=(index+(action==='nexttrack'?1:-1)+stations.length)%stations.length;by('elapsed').textContent='0:00';start(true);}}
for(const action of ['play','pause','stop','previoustrack','nexttrack'])if(session)try{session.setActionHandler(action,()=>command(action,'external'));supported.push(action);}catch{}
for(const action of ['seekbackward','seekforward','seekto'])if(session)try{session.setActionHandler(action,null);}catch{}
by('capability').textContent=supported.length===5?'외부 미디어 명령 연결 준비됨':supported.length?'일부 명령만 지원하는 브라우저예요.':'이 브라우저에서 외부 미디어 명령을 지원하지 않아요.';
by('play').addEventListener('click',()=>command(wanted?'pause':'play','screen'));by('previous').addEventListener('click',()=>command('previoustrack','screen'));by('next').addEventListener('click',()=>command('nexttrack','screen'));by('clear-log').addEventListener('click',()=>{rows=[];for(const action in counts)counts[action]=0;try{localStorage.removeItem(key);}catch{}drawLog();});
audio.addEventListener('playing',()=>{if(!wanted){audio.pause();return;}loading=false;failed=false;state('playing');metadata();by('play-status').textContent='재생 중';paint();});
audio.addEventListener('waiting',()=>{if(wanted){loading=true;by('play-status').textContent='방송을 받고 있어요…';paint();}});
audio.addEventListener('pause',()=>{if(!wanted||loading||!audio.paused)return;wanted=false;loading=false;state('paused');by('play-status').textContent='일시정지';paint();});
audio.addEventListener('ended',()=>{wanted=false;loading=false;failed=true;state('paused');by('play-status').textContent='방송 연결이 끝났어요. 다시 재생해 주세요.';paint();});
audio.addEventListener('error',()=>{if(!wanted)return;request++;wanted=false;loading=false;failed=true;state('paused');by('play-status').textContent='방송을 받을 수 없어요. 다시 재생하거나 다음 채널을 눌러 주세요.';paint();});
audio.addEventListener('timeupdate',()=>{const seconds=Math.max(0,Math.floor(Number(audio.currentTime)||0));by('elapsed').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');});drawLog();paint();
